import{_ as t,l as i,o as e,c as l,v as o,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Work-span 与 fork-join","description":"","frontmatter":{"title":"Work-span 与 fork-join","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/work-span-model.md","filePath":"cs/work-span-model.md","lastUpdated":1789023840000}'),h={name:"cs/work-span-model.md"};function _(k,a,P,m,f,u){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="work-span-与-fork-join" tabindex="-1">Work-span 与 fork-join <a class="header-anchor" href="#work-span-与-fork-join" aria-label="Permalink to &quot;Work-span 与 fork-join&quot;">​</a></h1><div class="epigraph"><p>工作 $W$ 是总运算，跨度 $S$ 是依赖最长链；贪心调度 $P$ 核上时间 $\\le W/P+S$。</p><footer>—— 据 Brent, The Parallel Evaluation of General Arithmetic Expressions, 1974；Cilk / Blumofe–Leiserson 工作窃取整理</footer></div><p>上一课<a href="/cs/pram-prefix-sum">PRAM 前缀和</a>给了 \\(W=O(n)\\)、\\(S=O(\\log n)\\)。缺口是 work-span 模型：不必假设 \\(n\\) 台处理器。fork-join：<code>spawn</code> 子任务，<code>sync</code> 等待。不重写前缀树。后课排序网络是比较器电路。Cilk 工作窃取期望。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DAG：结点运算，边依赖。\\(W=\\) 结点数，\\(S=\\) 最长路。Brent：\\(T_P\\le W/P+S\\)（忽略调度开销）。工作窃取：闲核偷他人双端子任务，空间与时间高概率近最优。</p><p>缺口是调度定律，不是再写前缀代码。</p><h3 id="不是-倍加速永远成立" tabindex="-1">不是 \\(P\\) 倍加速永远成立 <a class="header-anchor" href="#不是-倍加速永远成立" aria-label="Permalink to &quot;不是 $P$ 倍加速永远成立&quot;">​</a></h3><p>\\(S\\) 限制：\\(T_P\\ge S\\)。Amdahl 串行段。\\(W/P\\) 是另一下界。不要只报「并行了」。</p><p><span class="marginnote">Brent 1974。Blumofe–Leiserson Cilk。后课排序网络跨度是比较器层数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写分治：<code>fork</code> 两半，<code>join</code>，线性工作。分析 \\(W(n)=2W(n/2)+O(n)\\)，\\(S(n)=S(n/2)+O(1)\\)。加速比 \\(T_1/T_P\\)。</p>',11)),(e(),s(c,null,{default:r(()=>[p(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAG%5B%22%E8%AE%A1%E7%AE%97%20DAG%22%5D%20--%3E%20W%5B%22%E5%B7%A5%E4%BD%9C%20W%22%5D%0A%20%20DAG%20--%3E%20S%5B%22%E8%B7%A8%E5%BA%A6%20S%22%5D%0A%20%20W%20--%3E%20TP%5B%22T_P%20%E2%89%A4%20W%2FP%20%2B%20S%22%5D%0A%20%20S%20--%3E%20TP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>递归生成的任务树要足够粗，避免开销。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>任意时刻就绪任务 \\(\\ge\\) 可并行度。贪心总能让 \\(P\\) 核不闲除非不够任务。工作窃取把双端队列当任务池。与 PRAM：PRAM 假定同步与冲突规则；work-span 更接近语言。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU occupancy。不写锁。后课默认：并行算法报 \\(W\\) 与 \\(S\\)。下一课排序网络。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(T_P\\le W/P+S\\)；\\(T_P\\ge\\max(W/P,S)\\)。</li><li>fork-join 表达分治 DAG。</li><li>工作窃取近最优调度。</li><li>出处：Brent, 1974；Cilk 工作窃取。</li></ul>',7))])}const T=t(h,[["render",_]]);export{S as __pageData,T as default};
